import argparse
import shutil
import subprocess
import sys
import tomllib
from pathlib import Path


def templates_dir() -> Path:
    return Path(__file__).parent / "templates"


def fail(msg: str) -> None:
    print(f"[newsetup] error: {msg}", file=sys.stderr)
    sys.exit(1)


def run(cmd: str, cwd: Path) -> None:
    print(f"\n[newsetup] $ {cmd}  (in {cwd})")
    result = subprocess.run(cmd, cwd=str(cwd), shell=True)
    if result.returncode != 0:
        fail(f"command failed ({result.returncode}): {cmd}")


def load_manifest(template_dir: Path) -> dict:
    manifest = template_dir / "template.toml"
    if not manifest.exists():
        return {}
    return tomllib.loads(manifest.read_text(encoding="utf-8"))


def discover_modules(template_dir: Path, data: dict) -> list[str]:
    folders = {
        d.name
        for d in template_dir.iterdir()
        if d.is_dir() and d.name != "config"
    }
    declared = {k for k, v in data.items() if isinstance(v, dict)}
    return sorted(folders | declared)


def iter_files(root: Path):
    for p in sorted(root.rglob("*")):
        if p.is_file():
            yield p


def prompt_conflict(dest: Path) -> str:
    if not sys.stdin.isatty():
        fail(f"{dest} already exists (non-interactive shell; use --force to overwrite).")
    while True:
        ans = input(
            f"[newsetup] {dest} already exists. [o]verride / [m]erge / [s]kip? "
        ).strip().lower()
        if ans in ("o", "override"):
            return "override"
        if ans in ("m", "merge"):
            return "merge"
        if ans in ("s", "skip"):
            return "skip"
        print("  answer o, m, or s.")


def module_parts(section: dict) -> list[str]:
    parts = section.get("parts", []) if isinstance(section, dict) else []
    return list(parts) if isinstance(parts, list) else []


def resolve_parts(section: dict, requested: list[str]) -> list[str]:
    requires = section.get("requires", {}) if isinstance(section, dict) else {}
    selected = set(requested)
    changed = True
    while changed:
        changed = False
        for p in list(selected):
            for dep in requires.get(p, []):
                if dep not in selected:
                    selected.add(dep)
                    changed = True
    declared = module_parts(section)
    return [p for p in declared if p in selected]


def module_always(section: dict) -> list[str]:
    always = section.get("always", []) if isinstance(section, dict) else []
    return list(always) if isinstance(always, list) else []


def copy_parts_module(
    src_module: Path, dest_module: Path, parts: list[str], always: list[str] = ()
) -> None:
    dest_module.mkdir(parents=True, exist_ok=True)
    tfvars_chunks: list[str] = []
    for part in ["_core", *always, *parts]:
        pdir = src_module / part
        if not pdir.is_dir():
            continue
        for f in iter_files(pdir):
            if f.name.endswith(".tfvars.fragment"):
                tfvars_chunks.append(f.read_text(encoding="utf-8").rstrip("\n"))
                continue
            out = dest_module / f.relative_to(pdir)
            out.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(f, out)
    if tfvars_chunks:
        body = "\n\n".join(tfvars_chunks) + "\n"
        (dest_module / "terraform.tfvars.example").write_text(body, encoding="utf-8")


def cmd_list() -> None:
    root = templates_dir()
    found = False
    for tdir in sorted(p for p in root.iterdir() if p.is_dir()):
        data = load_manifest(tdir)
        desc = data.get("description", "")
        modules = discover_modules(tdir, data)
        found = True
        print(f"{tdir.name}" + (f" - {desc}" if desc else ""))
        print(f"  modules: {', '.join(modules) if modules else '(none)'}")
        for m in modules:
            section = data.get(m) if isinstance(data.get(m), dict) else {}
            parts = module_parts(section)
            if parts:
                print(f"    {m} parts: {', '.join(parts)}  (pick with --only)")
            always = module_always(section)
            if always:
                print(f"    {m} always: {', '.join(always)}  (every scaffold)")
        print("  (config root files always applied; use --bare for config only)")
    if not found:
        print(f"[newsetup] no templates in {root}")


def cmd_new(args: argparse.Namespace) -> None:
    if args.bare and (args.modules or args.only):
        fail("--bare cannot be combined with --modules or --only.")

    template_dir = templates_dir() / args.template
    if not template_dir.is_dir():
        fail(f"unknown template '{args.template}'. run `newsetup list` to see options.")

    data = load_manifest(template_dir)
    modules = discover_modules(template_dir, data)

    if args.bare:
        selected: list[str] = []
    elif args.modules:
        unknown = [m for m in args.modules if m not in modules]
        if unknown:
            avail = ", ".join(modules) if modules else "(none)"
            fail(f"unknown module(s): {', '.join(unknown)}. available: {avail}")
        selected = list(dict.fromkeys(args.modules))
    else:
        selected = modules

    # --only selects PARTS within a single part-aware module.
    if args.only:
        if len(selected) != 1:
            fail("--only selects parts within one module; pass exactly one via --modules.")
        only_module = selected[0]
        section = data.get(only_module) if isinstance(data.get(only_module), dict) else {}
        declared = module_parts(section)
        if not declared:
            fail(f"module '{only_module}' has no parts to pick with --only.")
        unknown = [p for p in args.only if p not in declared]
        if unknown:
            fail(f"unknown part(s) for {only_module}: {', '.join(unknown)}. parts: {', '.join(declared)}")

    target = Path(args.path).expanduser().resolve()
    target.mkdir(parents=True, exist_ok=True)
    config_dir = template_dir / "config"
    apply_config = config_dir.is_dir()

    for m in selected:
        d = target / m
        if d.exists() and any(d.iterdir()):
            fail(f"{d} already exists and is not empty. refusing to clobber.")

    config_decisions: dict[Path, str] = {}
    if apply_config:
        for f in iter_files(config_dir):
            dest = target / f.relative_to(config_dir)
            if dest.exists():
                config_decisions[dest] = "override" if args.force else prompt_conflict(dest)

    summary = "bare (config only)" if args.bare else (
        f"modules [{', '.join(selected)}] + config" if selected else "config only"
    )
    print(f"[newsetup] template '{args.template}' -> {target}  ({summary})")

    if (target / ".git").exists():
        print(f"[newsetup] git repo already exists in {target}, skipping git init")
    else:
        run("git init", target)

    for m in selected:
        section = data.get(m) if isinstance(data.get(m), dict) else {}
        declared = module_parts(section)
        if declared:
            requested = args.only if args.only else declared
            parts = resolve_parts(section, requested)
            always = module_always(section)
            copy_parts_module(template_dir / m, target / m, parts, always)
            shown = parts + [f"{a} (always)" for a in always]
            print(f"[newsetup] copied {m}/ parts: {', '.join(shown)}")
            continue
        cwd = section.get("cwd", ".")
        run_dir = target / cwd
        if cwd != ".":
            run_dir.mkdir(parents=True, exist_ok=True)
        for cmd in section.get("commands", []):
            run(cmd, run_dir)
        src = template_dir / m
        if src.is_dir():
            shutil.copytree(src, target / m, dirs_exist_ok=True)
            print(f"[newsetup] copied {m}/ template files")

    if apply_config:
        for f in iter_files(config_dir):
            dest = target / f.relative_to(config_dir)
            decision = config_decisions.get(dest)
            if decision == "skip":
                print(f"[newsetup] skipped {dest} (kept existing)")
                continue
            if decision == "merge":
                existing = dest.read_text(encoding="utf-8").rstrip("\n")
                addition = f.read_text(encoding="utf-8")
                dest.write_text(f"{existing}\n\n{addition}", encoding="utf-8")
                print(f"[newsetup] merged into {dest}")
                continue
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(f, dest)
            print(f"[newsetup] wrote {dest}")

    print(f"\n[newsetup] done. project ready at {target}")


def main() -> None:
    parser = argparse.ArgumentParser(
        prog="newsetup",
        description="Scaffold projects from templates.",
    )
    sub = parser.add_subparsers(dest="cmd", required=True)

    sub.add_parser("list", help="list available templates and their modules")

    p_new = sub.add_parser("new", help="scaffold a new project from a template")
    p_new.add_argument(
        "--path",
        required=True,
        help="where to scaffold: '.' for here, a name for ./<name>, or a full path",
    )
    p_new.add_argument(
        "--template",
        required=True,
        help="template to scaffold from (see `newsetup list`)",
    )
    p_new.add_argument(
        "--modules",
        nargs="+",
        metavar="MODULE",
        help="build only these modules (config root files are always included)",
    )
    p_new.add_argument(
        "--only",
        nargs="+",
        metavar="PART",
        help="build only these parts within a single selected module "
        "(e.g. for infra: ecr, rds, s3, ecs; iam is always included)",
    )
    p_new.add_argument(
        "--bare",
        action="store_true",
        help="config root files only, no modules",
    )
    p_new.add_argument(
        "-f",
        "--force",
        action="store_true",
        help="overwrite existing root config files without prompting "
        "(default: ask override/merge/skip per file)",
    )

    args = parser.parse_args()
    if args.cmd == "list":
        cmd_list()
    elif args.cmd == "new":
        cmd_new(args)

// The ecr slice of the GitHub Actions deploy role's permissions. The role lives
// in the always-on iam/ layer; this grant lights it up to push images to this
// repo. Only present when ecr is part of the scaffold.
data "aws_iam_policy_document" "github_actions_ecr" {
  statement {
    sid       = "EcrAuth"
    effect    = "Allow"
    actions   = ["ecr:GetAuthorizationToken"]
    resources = ["*"]
  }
  statement {
    sid    = "EcrPushPull"
    effect = "Allow"
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:GetDownloadUrlForLayer",
      "ecr:InitiateLayerUpload",
      "ecr:UploadLayerPart",
      "ecr:CompleteLayerUpload",
      "ecr:PutImage",
    ]
    resources = [
      aws_ecr_repository.backend.arn,
    ]
  }
}

resource "aws_iam_role_policy" "github_actions_ecr" {
  name   = "ecr-push"
  role   = aws_iam_role.github_actions_deploy.id
  policy = data.aws_iam_policy_document.github_actions_ecr.json
}

output "backend_service_arn" {
  value       = aws_ecs_express_gateway_service.backend.service_arn
  description = "ECS Express service ARN"
}

output "backend_ingress_paths" {
  value       = aws_ecs_express_gateway_service.backend.ingress_paths
  description = "Public endpoints (ALB DNS) for the backend"
}

output "ecs_task_execution_role_arn" {
  value       = aws_iam_role.ecs_task_execution.arn
  description = "ECS task execution role ARN"
}

output "ecs_infrastructure_role_arn" {
  value       = aws_iam_role.ecs_infrastructure_express.arn
  description = "ECS Express infrastructure role ARN"
}

