resource "aws_ecs_express_gateway_service" "backend" {
  service_name            = "${var.project}-${var.environment}-backend"
  execution_role_arn      = aws_iam_role.ecs_task_execution.arn
  infrastructure_role_arn = aws_iam_role.ecs_infrastructure_express.arn
  health_check_path       = "/admin/login/"

  primary_container {
    image          = "${aws_ecr_repository.backend.repository_url}:latest"
    container_port = 8000

    environment {
      name  = "CORS_ALLOWED_ORIGINS"
      value = var.frontend_origin
    }
    environment {
      name  = "IS_LOCAL"
      value = "False"
    }
    environment {
      name  = "PROD_DATABASE_URL"
      value = "postgres://${var.db_username}:${var.db_password}@${aws_db_instance.postgres.endpoint}/${replace(var.project, "-", "_")}?sslmode=require"
    }
    environment {
      name  = "DJANGO_ALLOWED_HOSTS"
      value = "*"
    }
    environment {
      name  = "DJANGO_DEBUG"
      value = "False"
    }
    environment {
      name  = "DJANGO_SECRET_KEY"
      value = var.django_secret_key
    }
  }
}

